+import React, { useState } from 'react';
+import { View, Text } from 'react-native';
+import { TimePicker } from '../components/TimePicker';
+
+export function FeedingScheduleEditor({ petId }: { petId: string }) {
+  const [times, setTimes] = useState<string[]>(['08:00', '18:00']);
+  const update = (i: number, v: string) =>
+    setTimes((prev) => prev.map((t, idx) => (idx === i ? v : t)));
+  return (
+    <View>
+      <Text>Daily feeding times</Text>
+      {times.map((t, i) => (
+        <TimePicker key={i} value={t} onChange={(v) => update(i, v)} />
+      ))}
+    </View>
+  );
+}

