+    // Retry outbound sync with exponential backoff (100ms, 200ms, 400ms).
+    let mut delay = Duration::from_millis(100);
+    for attempt in 0..3 {
+        match client.post(url).json(payload).send().await {
+            Ok(resp) if resp.status().is_success() => return Ok(()),
+            Ok(resp) if attempt == 2 => return Err(SyncError::Status(resp.status())),
+            Err(e) if attempt == 2 => return Err(SyncError::Transport(e)),
+            _ => tokio::time::sleep(delay).await,
+        }
+        delay *= 2;
+    }
+    Ok(())
 }

