+use chrono::{Duration, NaiveDate};
+
+/// Advance vaccination reminders fire 7 days before the due date.
+pub const LEAD_DAYS: i64 = 7;
+
+pub fn reminder_date(due: NaiveDate) -> NaiveDate {
+    due - Duration::days(LEAD_DAYS)
+}
+
+pub async fn schedule_advance_reminders(db: &Db, pet_id: Uuid) -> Result<(), Error> {
+    for vac in due_vaccinations(db, pet_id).await? {
+        let when = reminder_date(vac.due_date);
+        enqueue_notification(db, Notification {
+            pet_id,
+            kind: NotificationKind::VaccinationDue,
+            deliver_on: when,
+            body: format!("{} is due on {}", vac.name, vac.due_date),
+        }).await?;
+    }
+    Ok(())
+}

